function normalizeRecord(json) {
  if (!json) return null;

  if (Array.isArray(json.records)) {
    return json.records.map(normalizeRecord).filter(Boolean);
  }

  if (json.fields) {
    return {
      id: json.id || json.recordId,
      fields: json.fields,
    };
  }

  const { id, recordId, createdTime, ...rest } = json;

  return {
    id: id || recordId,
    fields: rest,
  };
}

function getRecords(nodeName) {
  const items = $items(nodeName) || [];
  const records = [];

  for (const item of items) {
    const normalized = normalizeRecord(item.json);

    if (Array.isArray(normalized)) {
      records.push(...normalized);
    } else if (normalized) {
      records.push(normalized);
    }
  }

  return records.filter((record) => record.id);
}

function asLinks(value) {
  if (!value) return [];

  if (Array.isArray(value)) {
    return value
      .map((item) => {
        if (typeof item === "string") return item;
        if (item?.id) return item.id;
        if (item?.recordId) return item.recordId;
        return String(item || "");
      })
      .map((item) => item.trim())
      .filter(Boolean);
  }

  if (typeof value === "string") {
    return [value.trim()].filter(Boolean);
  }

  return [];
}

function getString(value) {
  return String(value || "").trim();
}

function hasValue(value) {
  if (value === null || value === undefined) return false;
  if (Array.isArray(value)) return value.length > 0;
  return getString(value) !== "";
}

function getNumber(value) {
  const numberValue = Number(value);
  return Number.isFinite(numberValue) ? numberValue : null;
}

function todayDate() {
  return new Date().toISOString().slice(0, 10);
}

const users = getRecords("GET Users");
const classes = getRecords("GET Classes");
const memberships = getRecords("GET Memberships");
const assignments = getRecords("GET Assignments");
const submissions = getRecords("GET Submissions");
const grades = getRecords("GET Grades");
const attendance = getRecords("GET Attendance");
const notifications = getRecords("GET Notifications");
const predictions = getRecords("GET Predictions");
const existingAuditLogs = getRecords("GET Existing Audit Logs");

const today = todayDate();

const existingAuditText = existingAuditLogs
  .map((log) => getString(log.fields.Aciklama))
  .join("\n");

const output = [];

function addFinding({
  tableName,
  recordId,
  issueCode,
  title,
  description,
  oldValue = "",
  newValue = "",
  severity = "Uyarı",
}) {
  const trackingCode = `DATA_QUALITY:${today}:${tableName}:${recordId}:${issueCode}`;

  if (existingAuditText.includes(trackingCode)) {
    return;
  }

  output.push({
    json: {
      trackingCode,
      severity,
      fields: {
        Islem_Adi: title,
        Islem_Turu: "Veri Kalite Kontrolü",
        Tablo_Adi: tableName,
        Kayit_ID: recordId,
        Eski_Deger: oldValue,
        Yeni_Deger: newValue,
        IP_Adresi: "n8n-system",
        Aciklama: `${description}\n\nSistem takip kodu: ${trackingCode}`,
        Islem_Tarihi: today,
      },
    },
  });
}

const userIds = new Set(users.map((item) => item.id));
const classIds = new Set(classes.map((item) => item.id));
const assignmentIds = new Set(assignments.map((item) => item.id));

// Kullanicilar checks
for (const user of users) {
  const name = getString(user.fields.Ad_Soyad);
  const email = getString(user.fields.Eposta);
  const role = getString(user.fields.Rol);

  if (!name) {
    addFinding({
      tableName: "Kullanicilar",
      recordId: user.id,
      issueCode: "MISSING_NAME",
      title: "Kullanıcı ad soyad eksik",
      description: "Bir kullanıcı kaydında Ad_Soyad alanı boş.",
      severity: "Uyarı",
    });
  }

  if (!email) {
    addFinding({
      tableName: "Kullanicilar",
      recordId: user.id,
      issueCode: "MISSING_EMAIL",
      title: "Kullanıcı e-posta eksik",
      description: "Bir kullanıcı kaydında Eposta alanı boş. E-posta bildirimleri çalışmayabilir.",
      severity: "Kritik",
    });
  }

  if (!role) {
    addFinding({
      tableName: "Kullanicilar",
      recordId: user.id,
      issueCode: "MISSING_ROLE",
      title: "Kullanıcı rolü eksik",
      description: "Bir kullanıcı kaydında Rol alanı boş. Yetkilendirme ve yönlendirme sorunları oluşabilir.",
      severity: "Uyarı",
    });
  }
}

// Siniflar checks
for (const classRecord of classes) {
  const className =
    getString(classRecord.fields.Sinif_Adi) ||
    getString(classRecord.fields.Ders_Adi);

  const teacherIds = asLinks(classRecord.fields.Ogretmen);

  if (!className) {
    addFinding({
      tableName: "Siniflar",
      recordId: classRecord.id,
      issueCode: "MISSING_CLASS_NAME",
      title: "Sınıf adı eksik",
      description: "Bir sınıf kaydında Sinif_Adi veya Ders_Adi boş.",
      severity: "Uyarı",
    });
  }

  if (teacherIds.length === 0) {
    addFinding({
      tableName: "Siniflar",
      recordId: classRecord.id,
      issueCode: "MISSING_TEACHER",
      title: "Sınıf öğretmeni eksik",
      description: "Bir sınıf kaydında Ogretmen bağlantısı yok. Öğretmen panelleri ve bildirimler etkilenebilir.",
      severity: "Kritik",
    });
  }

  for (const teacherId of teacherIds) {
    if (!userIds.has(teacherId)) {
      addFinding({
        tableName: "Siniflar",
        recordId: classRecord.id,
        issueCode: "BROKEN_TEACHER_LINK",
        title: "Sınıf öğretmen bağlantısı bozuk",
        description: `Sınıf kaydında bulunamayan bir öğretmen bağlantısı var: ${teacherId}`,
        oldValue: teacherId,
        severity: "Kritik",
      });
    }
  }
}

// Sinif_Uyelikleri checks
for (const membership of memberships) {
  const membershipUserIds = asLinks(membership.fields.Kullanici);
  const membershipClassIds = asLinks(membership.fields.Sinif);
  const status = getString(membership.fields.Durum);
  const role = getString(membership.fields.Uyelik_Rolu);

  if (membershipUserIds.length === 0) {
    addFinding({
      tableName: "Sinif_Uyelikleri",
      recordId: membership.id,
      issueCode: "MISSING_USER_LINK",
      title: "Üyelik kullanıcı bağlantısı eksik",
      description: "Bir sınıf üyeliğinde Kullanici bağlantısı yok.",
      severity: "Kritik",
    });
  }

  if (membershipClassIds.length === 0) {
    addFinding({
      tableName: "Sinif_Uyelikleri",
      recordId: membership.id,
      issueCode: "MISSING_CLASS_LINK",
      title: "Üyelik sınıf bağlantısı eksik",
      description: "Bir sınıf üyeliğinde Sinif bağlantısı yok.",
      severity: "Kritik",
    });
  }

  if (!status) {
    addFinding({
      tableName: "Sinif_Uyelikleri",
      recordId: membership.id,
      issueCode: "MISSING_STATUS",
      title: "Üyelik durumu eksik",
      description: "Bir sınıf üyeliğinde Durum alanı boş.",
      severity: "Uyarı",
    });
  }

  if (!role) {
    addFinding({
      tableName: "Sinif_Uyelikleri",
      recordId: membership.id,
      issueCode: "MISSING_ROLE",
      title: "Üyelik rolü eksik",
      description: "Bir sınıf üyeliğinde Uyelik_Rolu alanı boş.",
      severity: "Uyarı",
    });
  }
}

// Odevler checks
for (const assignment of assignments) {
  const title = getString(assignment.fields.Odev_Basligi);
  const assignmentClassIds = asLinks(assignment.fields.Sinif);

  if (!title) {
    addFinding({
      tableName: "Odevler",
      recordId: assignment.id,
      issueCode: "MISSING_TITLE",
      title: "Ödev başlığı eksik",
      description: "Bir ödev kaydında Odev_Basligi alanı boş.",
      severity: "Uyarı",
    });
  }

  if (assignmentClassIds.length === 0) {
    addFinding({
      tableName: "Odevler",
      recordId: assignment.id,
      issueCode: "MISSING_CLASS_LINK",
      title: "Ödev sınıf bağlantısı eksik",
      description: "Bir ödev kaydında Sinif bağlantısı yok.",
      severity: "Kritik",
    });
  }
}

// Odev_Teslimleri checks
for (const submission of submissions) {
  const submissionAssignmentIds = asLinks(submission.fields.Odev);
  const submissionStudentIds = asLinks(submission.fields.Ogrenci);
  const submissionClassIds = asLinks(submission.fields.Sinif);

  if (submissionAssignmentIds.length === 0) {
    addFinding({
      tableName: "Odev_Teslimleri",
      recordId: submission.id,
      issueCode: "MISSING_ASSIGNMENT_LINK",
      title: "Ödev teslimi ödev bağlantısı eksik",
      description: "Bir ödev teslim kaydında Odev bağlantısı yok.",
      severity: "Kritik",
    });
  }

  for (const assignmentId of submissionAssignmentIds) {
    if (!assignmentIds.has(assignmentId)) {
      addFinding({
        tableName: "Odev_Teslimleri",
        recordId: submission.id,
        issueCode: "BROKEN_ASSIGNMENT_LINK",
        title: "Ödev teslimi bozuk ödev bağlantısı",
        description: `Ödev teslim kaydı bulunamayan bir ödeve bağlı: ${assignmentId}`,
        oldValue: assignmentId,
        severity: "Kritik",
      });
    }
  }

  if (submissionStudentIds.length === 0) {
    addFinding({
      tableName: "Odev_Teslimleri",
      recordId: submission.id,
      issueCode: "MISSING_STUDENT_LINK",
      title: "Ödev teslimi öğrenci bağlantısı eksik",
      description: "Bir ödev teslim kaydında Ogrenci bağlantısı yok.",
      severity: "Kritik",
    });
  }

  if (submissionClassIds.length === 0) {
    addFinding({
      tableName: "Odev_Teslimleri",
      recordId: submission.id,
      issueCode: "MISSING_CLASS_LINK",
      title: "Ödev teslimi sınıf bağlantısı eksik",
      description: "Bir ödev teslim kaydında Sinif bağlantısı yok.",
      severity: "Uyarı",
    });
  }
}

// Notlar checks
for (const grade of grades) {
  const gradeStudentIds = asLinks(grade.fields.Ogrenci);
  const gradeClassIds = asLinks(grade.fields.Sinif);
  const type = getString(grade.fields.Not_Turu);
  const score = getNumber(grade.fields.Puan);
  const publishStatus = getString(grade.fields.Yayin_Durumu);

  if (gradeStudentIds.length === 0) {
    addFinding({
      tableName: "Notlar",
      recordId: grade.id,
      issueCode: "MISSING_STUDENT_LINK",
      title: "Not öğrenci bağlantısı eksik",
      description: "Bir not kaydında Ogrenci bağlantısı yok.",
      severity: "Kritik",
    });
  }

  if (gradeClassIds.length === 0) {
    addFinding({
      tableName: "Notlar",
      recordId: grade.id,
      issueCode: "MISSING_CLASS_LINK",
      title: "Not sınıf bağlantısı eksik",
      description: "Bir not kaydında Sinif bağlantısı yok.",
      severity: "Kritik",
    });
  }

  if (!type) {
    addFinding({
      tableName: "Notlar",
      recordId: grade.id,
      issueCode: "MISSING_GRADE_TYPE",
      title: "Not türü eksik",
      description: "Bir not kaydında Not_Turu alanı boş.",
      severity: "Uyarı",
    });
  }

  if (score === null) {
    addFinding({
      tableName: "Notlar",
      recordId: grade.id,
      issueCode: "MISSING_SCORE",
      title: "Not puanı eksik",
      description: "Bir not kaydında Puan alanı boş.",
      severity: "Uyarı",
    });
  }

  if (!publishStatus) {
    addFinding({
      tableName: "Notlar",
      recordId: grade.id,
      issueCode: "MISSING_PUBLISH_STATUS",
      title: "Not yayın durumu eksik",
      description: "Bir not kaydında Yayin_Durumu alanı boş. Bildirim ve tahmin otomasyonları etkilenebilir.",
      severity: "Uyarı",
    });
  }
}

// Yoklamalar checks
for (const attendanceRecord of attendance) {
  if (asLinks(attendanceRecord.fields.Ogrenci).length === 0) {
    addFinding({
      tableName: "Yoklamalar",
      recordId: attendanceRecord.id,
      issueCode: "MISSING_STUDENT_LINK",
      title: "Yoklama öğrenci bağlantısı eksik",
      description: "Bir yoklama kaydında Ogrenci bağlantısı yok.",
      severity: "Kritik",
    });
  }

  if (asLinks(attendanceRecord.fields.Sinif).length === 0) {
    addFinding({
      tableName: "Yoklamalar",
      recordId: attendanceRecord.id,
      issueCode: "MISSING_CLASS_LINK",
      title: "Yoklama sınıf bağlantısı eksik",
      description: "Bir yoklama kaydında Sinif bağlantısı yok.",
      severity: "Kritik",
    });
  }

  if (!hasValue(attendanceRecord.fields.Tarih)) {
    addFinding({
      tableName: "Yoklamalar",
      recordId: attendanceRecord.id,
      issueCode: "MISSING_DATE",
      title: "Yoklama tarihi eksik",
      description: "Bir yoklama kaydında Tarih alanı boş.",
      severity: "Uyarı",
    });
  }

  if (!hasValue(attendanceRecord.fields.Durum)) {
    addFinding({
      tableName: "Yoklamalar",
      recordId: attendanceRecord.id,
      issueCode: "MISSING_STATUS",
      title: "Yoklama durumu eksik",
      description: "Bir yoklama kaydında Durum alanı boş.",
      severity: "Uyarı",
    });
  }
}

// Bildirimler checks
for (const notification of notifications) {
  if (asLinks(notification.fields.Alici).length === 0) {
    addFinding({
      tableName: "Bildirimler",
      recordId: notification.id,
      issueCode: "MISSING_RECIPIENT",
      title: "Bildirim alıcısı eksik",
      description: "Bir bildirim kaydında Alici bağlantısı yok.",
      severity: "Kritik",
    });
  }

  if (!hasValue(notification.fields.Mesaj)) {
    addFinding({
      tableName: "Bildirimler",
      recordId: notification.id,
      issueCode: "MISSING_MESSAGE",
      title: "Bildirim mesajı eksik",
      description: "Bir bildirim kaydında Mesaj alanı boş.",
      severity: "Uyarı",
    });
  }
}

// Tahminler checks
for (const prediction of predictions) {
  if (asLinks(prediction.fields.Ogrenci).length === 0) {
    addFinding({
      tableName: "Tahminler",
      recordId: prediction.id,
      issueCode: "MISSING_STUDENT_LINK",
      title: "Tahmin öğrenci bağlantısı eksik",
      description: "Bir tahmin kaydında Ogrenci bağlantısı yok.",
      severity: "Kritik",
    });
  }

  if (asLinks(prediction.fields.Sinif).length === 0) {
    addFinding({
      tableName: "Tahminler",
      recordId: prediction.id,
      issueCode: "MISSING_CLASS_LINK",
      title: "Tahmin sınıf bağlantısı eksik",
      description: "Bir tahmin kaydında Sinif bağlantısı yok.",
      severity: "Kritik",
    });
  }

  if (!hasValue(prediction.fields.Risk_Seviyesi)) {
    addFinding({
      tableName: "Tahminler",
      recordId: prediction.id,
      issueCode: "MISSING_RISK_LEVEL",
      title: "Tahmin risk seviyesi eksik",
      description: "Bir tahmin kaydında Risk_Seviyesi alanı boş.",
      severity: "Uyarı",
    });
  }
}

// If everything is clean, write one success audit row per day.
if (output.length === 0) {
  addFinding({
    tableName: "Sistem",
    recordId: `SYSTEM-${today}`,
    issueCode: "NO_DATA_QUALITY_ISSUE",
    title: "Veri kalite kontrolü tamamlandı",
    description: "Günlük veri kalite kontrolünde kritik veya uyarı düzeyinde sorun bulunmadı.",
    newValue: "Temiz",
    severity: "Bilgi",
  });
}

return output;
